const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const MAP = {
  connection_accepted:'linkedin_accept', invite_accepted:'linkedin_accept', connectionaccepted:'linkedin_accept', accepted:'linkedin_accept', linkedin_accept:'linkedin_accept', connection_request_accepted:'linkedin_accept',
  reply:'linkedin_reply', message_reply:'linkedin_reply', replied:'linkedin_reply', new_reply:'linkedin_reply', inmail_reply:'linkedin_reply', message_received:'linkedin_reply', linkedin_reply:'linkedin_reply', message_reply_received:'linkedin_reply', inmail_reply_received:'linkedin_reply', every_message_inmail_reply_received:'linkedin_reply', reply_received:'linkedin_reply',
  profile_view:'linkedin_profile_view', profile_visit:'linkedin_profile_view', profileview:'linkedin_profile_view', linkedin_profile_view:'linkedin_profile_view', viewed_profile:'linkedin_profile_view',
  post_engagement:'linkedin_post_engage', reaction:'linkedin_post_engage', like:'linkedin_post_engage', comment:'linkedin_post_engage', post_engage:'linkedin_post_engage', linkedin_post_engage:'linkedin_post_engage', liked_post:'linkedin_post_engage', post_liked:'linkedin_post_engage'
};
const nameOf = (o) => {
  if (!o) return '';
  if (typeof o === 'string') return o;
  if (typeof o === 'object') return o.name || o.fullName || o.full_name || [o.firstName || o.first_name, o.lastName || o.last_name].filter(Boolean).join(' ') || o.profileUrl || o.profile_url || '';
  return '';
};
const campaignOf = (c) => {
  if (!c) return '';
  if (typeof c === 'string') return c;
  if (typeof c === 'object') return c.utm_campaign || c.name || '';
  return '';
};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const b = (j.body && typeof j.body === 'object') ? j.body : j;
  const events = Array.isArray(b) ? b : (Array.isArray(b.events) ? b.events : [b]);
  for (const ev of events) {
    if (!ev || typeof ev !== 'object') continue;
    const raw = String(ev.event_type || ev.event || ev.type || ev.eventType || ev.webhookEventType || '').trim().toLowerCase().replace(/[\s\/.-]+/g, '_');
    const et = MAP[raw];
    if (!et) continue;
    const campaign = ev.utm_campaign || campaignOf(ev.campaign) || ev.campaign_name || ev.campaignName || (ev.tracking && ev.tracking.utm_campaign) || '';
    const account = ev.account || (ev.lead && (ev.lead.companyName || ev.lead.company)) || '';
    const contact = ev.contact || ev.name || ev.full_name || ev.prospect || nameOf(ev.lead) || nameOf(ev.correspondent) || '';
    const eventId = ev.event_id || ev.id || ev.activity_id || ev.webhookEventId || '';
    const occurred = ev.occurred_at || ev.timestamp || ev.created_at || ev.createdAt || ev.time || new Date().toISOString();
    const value = (ev.value != null && ev.value !== '') ? Number(ev.value) : 1;
    const meta = { linkedin_event_id: String(eventId), raw_event: String(ev.event_type || ev.event || ev.type || ev.eventType || ev.webhookEventType || ''), tool: String(ev.tool || ev.source || 'linkedin') };
    if (ev.headline) meta.headline = String(ev.headline).slice(0, 200);
    const msg = ev.message || ev.reply_body || ev.messageText || (ev.reply && ev.reply.text) || '';
    if (et === 'linkedin_reply' && msg) meta.reply_snippet = String(msg).slice(0, 200);
    const profileUrl = (ev.lead && (ev.lead.profileUrl || ev.lead.profile_url)) || ev.profileUrl || ev.profile_url || '';
    if (profileUrl) meta.profile_url = String(profileUrl).slice(0, 300);
    out.push({ json: {
      account_esc: esc(account),
      contact_esc: esc(contact),
      campaign_esc: esc(campaign),
      event_type: et,
      event_id_esc: esc(eventId),
      value: Number.isFinite(value) ? value : 1,
      occurred_esc: esc(occurred),
      metadata_esc: esc(JSON.stringify(meta))
    } });
  }
}
return out;
